import { STORE_ORDER_STATUS } from "@/lib/admin/status";
import type { AdminOrderDetail, AdminOrderListItem } from "@/lib/admin/types";
import type { Pagination as PaginationType } from "@/lib/api";
import { classifyStatus } from "@/lib/apiFailure";
import { formatCurrency, formatDate, formatDateTime, formatNumber } from "@/lib/format";
import { t } from "@/lib/strings";

const COLUMNS = [
  t.admin.orders.colOrderNumber,
  t.admin.orders.colStore,
  t.admin.orders.colCustomer,
  t.admin.orders.colItems,
  t.admin.orders.colDate,
  t.admin.orders.colTotal,
  t.admin.orders.colStatus,
  t.admin.orders.colAction,
] as const;

export default function AdminOrdersPage() {
  const [orders, setOrders] = useState<AdminOrderListItem[]>([]);
  const [pagination, setPagination] = useState<PaginationType | null>(null);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [attempt, setAttempt] = useState(0);
  const [detail, setDetail] = useState<AdminOrderDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      const res = await fetchAdminOrders({ page, limit: 20 });
      if (cancelled) return;
      setLoading(false);
      if (res.success && res.orders) {
        setOrders(res.orders);
        setPagination(res.pagination ?? null);
        setError("");
        return;
      }
      const failure = classifyStatus(res);
      setError(failure.kind === "unauthorized" ? t.admin.common.sessionInvalid : failure.message);
    })();
    return () => { cancelled = true; };
  }, [page, attempt]);

  const openDetail = async (orderId: number) => {
    setDetailLoading(true);
    setDetail(null);
    const res = await fetchAdminOrderDetail(orderId);
    setDetailLoading(false);
    if (res.success && res.order) {
      setDetail(res.order);
      return;
    }
    const failure = classifyStatus(res);
    setError(failure.kind === "unauthorized" ? t.admin.common.sessionInvalid : failure.message);
  };

  const total = pagination?.total ?? orders.length;
  const delivery = detail?.delivery;
  const deliveryAddress = [delivery?.city, delivery?.area, delivery?.street, delivery?.details]
    .filter(Boolean)
    .join(" — ");
  const productsTotal = detail?.money?.productsTotal ?? detail?.total ?? "0";
  const deliveryFee = detail?.money?.deliveryFee ?? delivery?.fee;
  return (
    <div className="flex flex-col gap-6">
      <PageHeader title={t.admin.orders.title} subtitle={total ? `${formatNumber(total)} ${t.admin.orders.count}` : t.admin.orders.globalSubtitle} />
      <ErrorBanner message={error} onRetry={() => setAttempt((value) => value + 1)} />

      {loading ? <Spinner /> : orders.length === 0 ? (
        <Card><CardBody className="p-8"><EmptyState icon={ShoppingBag} title={t.admin.orders.empty} hint={t.admin.orders.globalSubtitle} /></CardBody></Card>
      ) : (
        <div className="flex flex-col gap-4">
          <Card className="overflow-hidden border border-border shadow-xs">
            <TableShell minWidth="min-w-[900px]"><Thead columns={COLUMNS} /><tbody className="divide-y divide-border/60">
              {orders.map((order) => <tr key={order.id} className="bg-surface transition hover:bg-primary-soft/40">
                <Td className="font-extrabold text-heading">{order.orderNumber}</Td>
                <Td>{order.store?.name ?? t.admin.common.none}</Td>
                <Td><p className="font-semibold text-heading">{order.customer?.name ?? order.recipientName}</p><p className="mt-1 text-xs text-text-secondary">{order.city ?? t.admin.common.none}</p></Td>
                <Td className="ltr-nums">{formatNumber(order.itemsCount)}</Td>
                <Td className="ltr-nums whitespace-nowrap text-text-secondary">{formatDate(order.createdAt)}</Td>
                <Td className="ltr-nums font-bold">{formatCurrency(Number(order.total))}</Td>
                <Td><StatusBadge meta={STORE_ORDER_STATUS[order.status]} /></Td>
                <Td><Button size="sm" variant="secondary" onClick={() => openDetail(order.id)} icon={<Eye className="size-3.5" aria-hidden="true" />}>{t.admin.orders.reviewOrder}</Button></Td>
              </tr>)}
            </tbody></TableShell>
          </Card>
          {pagination && <Pagination pagination={pagination} onChange={setPage} />}
        </div>
      )}

      {(detailLoading || detail) && <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
        <button type="button" className="fixed inset-0 bg-black/40 backdrop-blur-xs" aria-label={t.common.close} onClick={() => !detailLoading && setDetail(null)} />
        <div className="relative z-10 max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-3xl border border-border bg-app-bg shadow-2xl">
          <div className="sticky top-0 z-10 flex items-start justify-between border-b border-border bg-surface px-6 py-5 sm:px-8">
            <div><h2 className="text-xl font-black text-heading">{t.admin.orders.detailsTitle}</h2>{detail && <p className="mt-1 ltr-nums text-sm font-semibold text-text-secondary">{detail.orderNumber}</p>}</div>
            <Button variant="ghost" size="sm" disabled={detailLoading} onClick={() => setDetail(null)} icon={<X className="size-4" aria-hidden="true" />}>{t.common.close}</Button>
          </div>
          {detailLoading ? <div className="p-12"><Spinner /></div> : detail && <div className="space-y-5 p-5 sm:p-8">
            <section className="flex flex-col gap-4 rounded-2xl bg-primary p-5 text-icon sm:flex-row sm:items-center sm:justify-between">
              <div><p className="text-xs font-bold text-icon/70">حالة الطلب</p><div className="mt-2"><StatusBadge meta={STORE_ORDER_STATUS[detail.status]} /></div></div>
              <div className="grid grid-cols-2 gap-5 text-start sm:text-end"><div><p className="text-xs font-bold text-icon/70">إجمالي المنتجات</p><p className="mt-1 ltr-nums text-lg font-black">{formatCurrency(Number(productsTotal))}</p></div><div><p className="text-xs font-bold text-icon/70">الإجمالي المطلوب</p><p className="mt-1 ltr-nums text-lg font-black">{formatCurrency(Number(detail.total))}</p></div></div>
            </section>

            <div className="grid gap-5 md:grid-cols-2">
              <Card className="border border-border shadow-xs"><CardHeader title={t.admin.orders.customerInfo} /><CardBody><InfoGrid rows={[
                { label: t.admin.orders.colCustomer, value: detail.customer.name },
                { label: t.admin.users.email, value: <span dir="ltr">{detail.customer.email}</span> },
                { label: t.admin.users.phone, value: <span dir="ltr">{delivery?.recipientPhone ?? detail.customer.phone ?? t.admin.common.none}</span> },
                { label: t.admin.common.createdAt, value: <span className="ltr-nums">{formatDateTime(detail.createdAt)}</span> },
              ]} /></CardBody></Card>
              <Card className="border border-border shadow-xs"><CardHeader title={t.admin.orders.shippingAddress} /><CardBody><InfoGrid rows={[
                { label: t.admin.orders.colStore, value: detail.store.name },
                { label: "العنوان", value: deliveryAddress || t.admin.common.none },
                { label: "اسم المستلم", value: delivery?.recipientName ?? detail.customer.name },
                { label: "رسوم التوصيل", value: deliveryFee === null || deliveryFee === undefined ? t.admin.orders.freeShipping : <span className="ltr-nums">{formatCurrency(Number(deliveryFee))}</span> },
              ]} /></CardBody></Card>
            </div>

            <Card className="overflow-hidden border border-border shadow-xs"><CardHeader title={t.admin.orders.itemsList} /><CardBody className="p-0"><div className="divide-y divide-border/70">{detail.items.map((item) => {
              const unitPrice = item.unitPrice ?? item.price;
              const lineTotal = item.lineTotal ?? String(item.quantity * Number(unitPrice));
              const variant = [item.colorName ?? item.variant, item.sizeName ?? item.size].filter(Boolean).join(" · ");
              const image = item.image ?? item.productImage;
              return <article key={item.id} className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between">
                <div className="flex min-w-0 items-center gap-4">{image ? <img src={image} alt="" className="size-16 shrink-0 rounded-xl border border-border object-cover" /> : <span className="grid size-16 shrink-0 place-items-center rounded-xl bg-field-bg text-xs font-bold text-text-secondary">منتج</span>}<div className="min-w-0"><p className="truncate text-base font-extrabold text-heading">{item.productName}</p>{variant && <p className="mt-1 text-sm text-text-secondary">{variant}</p>}</div></div>
                <div className="grid grid-cols-3 gap-3 rounded-xl bg-field-bg p-3 text-center sm:min-w-[290px]"><div><p className="text-[11px] font-bold text-text-secondary">عدد القطع</p><p className="mt-1 ltr-nums font-black text-heading">{item.quantity}</p></div><div><p className="text-[11px] font-bold text-text-secondary">سعر القطعة</p><p className="mt-1 ltr-nums font-black text-heading">{formatCurrency(Number(unitPrice))}</p></div><div><p className="text-[11px] font-bold text-text-secondary">إجمالي المنتج</p><p className="mt-1 ltr-nums font-black text-primary">{formatCurrency(Number(lineTotal))}</p></div></div>
              </article>;
            })}</div></CardBody></Card>
          </div>}
        </div>
      </div>}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import {
  ArrowLeft,
  Ban,
  Calendar,
  Check,
  CircleCheck,
  CreditCard,
  DollarSign,
  ExternalLink,
  Mail,
  MapPin,
  Package,
  Phone,
  Power,
  PowerOff,
  RotateCcw,
  ShieldCheck,
  ShieldOff,
  ShoppingBag,
  Star,
  StarOff,
  Store as StoreIcon,
  Tag,
  Trash2,
  TriangleAlert,
  User,
} from "lucide-react";
import { Card, CardBody, CardHeader } from "@/components/ui/Card";
import Badge from "@/components/ui/Badge";
import Button from "@/components/ui/Button";
import ConfirmDialog from "@/components/ui/ConfirmDialog";
import ReasonDialog from "@/components/ui/ReasonDialog";
import EmptyState from "@/components/ui/EmptyState";
import ErrorBanner from "@/components/ui/ErrorBanner";
import Spinner from "@/components/ui/Spinner";
import InfoGrid from "@/components/admin/InfoGrid";
import StatusBadge from "@/components/admin/StatusBadge";
import StoreOrdersSection from "@/components/admin/StoreOrdersSection";
import {
  activateStore,
  activateUser,
  approveStore,
  deleteStore,
  featureStore,
  fetchStore,
  rejectStore,
  suspendStore,
  suspendUser,
  unfeatureStore,
} from "@/lib/admin/api";
import { accountStatus, STORE_STATUS } from "@/lib/admin/status";
import type { AdminStoreDetail, StoreOwner } from "@/lib/admin/types";
import { classifyStatus } from "@/lib/apiFailure";
import { formatCurrency, formatDate, formatNumber } from "@/lib/format";
import { isBrokenText, textOrNull } from "@/lib/brokenText";
import { useFlash } from "@/lib/useFlash";
import { t } from "@/lib/strings";

type Dialog =
  | "approve"
  | "reject"
  | "rereview"
  | "suspend"
  | "activate"
  | "feature"
  | "unfeature"
  | "delete"
  | null;

type ActiveSection = "info" | "orders";

export default function AdminStoreDetailPage() {
  const router = useRouter();
  const routeParams = useParams<{ id: string }>();
  const rawId = routeParams?.id;
  const storeId = rawId ? Number(rawId) : NaN;
  const validId = Number.isSafeInteger(storeId) && storeId > 0;

  const [store, setStore] = useState<AdminStoreDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [error, setError] = useState("");
  const [attempt, setAttempt] = useState(0);
  const [activeSection, setActiveSection] = useState<ActiveSection>("info");

  const [dialog, setDialog] = useState<Dialog>(null);
  const [busy, setBusy] = useState(false);
  const [reasonError, setReasonError] = useState<string>();
  const [flash, showFlash] = useFlash();

  useEffect(() => {
    if (!validId) {
      return;
    }

    let cancelled = false;

    (async () => {
      const res = await fetchStore(storeId);
      if (cancelled) return;

      setLoading(false);

      if (res.success && res.store) {
        const normalizedStore: AdminStoreDetail = {
          ...res.store,
          owner: res.store.owner
            ? {
                ...res.store.owner,
              }
            : ({
                id: 0,
                name: "",
                email: "",
                phone: null,
                emailVerified: false,
                isActive: false,
                createdAt: "",
              } as StoreOwner),
          categories: Array.isArray(res.store.categories)
            ? res.store.categories
            : [],
        };
        setStore(normalizedStore);
        setNotFound(false);
        setError("");
        return;
      }

      const failure = classifyStatus(res);
      if (failure.kind === "notFound" || failure.kind === "noStore") {
        setNotFound(true);
        return;
      }
      setError(
        failure.kind === "unauthorized"
          ? t.admin.common.sessionInvalid
          : failure.message,
      );
    })();

    return () => {
      cancelled = true;
    };
  }, [storeId, validId, attempt]);

  const handleApprove = useCallback(
    async (successMsg: string) => {
      setBusy(true);
      setError("");

      const res = await approveStore(storeId);
      if (!res.success) {
        setBusy(false);
        setDialog(null);
        const failure = classifyStatus(res);
        setError(
          failure.kind === "unauthorized"
            ? t.admin.common.sessionInvalid
            : failure.message,
        );
        return;
      }

      if (store?.owner?.id) {
        const ownerResult = await activateUser(store.owner.id);
        if (!ownerResult.success) {
          if (res.store) setStore(res.store);
          setBusy(false);
          setDialog(null);
          setError(`تم قبول المتجر، لكن تعذر تفعيل حساب المالك: ${ownerResult.message || t.admin.common.loadFailed}`);
          return;
        }
      }

      const updatedStore: AdminStoreDetail = res.store
        ? {
            ...res.store,
            isActive: true,
            owner: {
              ...res.store.owner,
              isActive: true,
            },
          }
        : {
            ...store!,
            status: "APPROVED",
            isActive: true,
            rejectionReason: null,
            owner: {
              ...store!.owner,
              isActive: true,
            },
          };

      setStore(updatedStore);
      setBusy(false);
      setDialog(null);
      showFlash(successMsg);
    },
    [storeId, store, showFlash],
  );

  const handleReject = useCallback(
    async (reason: string) => {
      setBusy(true);
      setError("");
      setReasonError(undefined);

      const res = await rejectStore(storeId, reason);
      if (!res.success) {
        setBusy(false);
        const failure = classifyStatus(res);
        if (failure.kind === "validation" && failure.errors?.reason) {
          setReasonError(failure.errors.reason);
          return;
        }
        setDialog(null);
        setError(
          failure.kind === "unauthorized"
            ? t.admin.common.sessionInvalid
            : failure.message,
        );
        return;
      }

      if (store?.owner?.id) {
        const ownerResult = await suspendUser(store.owner.id);
        if (!ownerResult.success) {
          if (res.store) setStore(res.store);
          setBusy(false);
          setDialog(null);
          setError(`تم رفض المتجر، لكن تعذر إيقاف حساب المالك: ${ownerResult.message || t.admin.common.loadFailed}`);
          return;
        }
      }

      const updatedStore: AdminStoreDetail = res.store
        ? {
            ...res.store,
            status: "REJECTED",
            isActive: false,
            rejectionReason: reason,
            owner: {
              ...res.store.owner,
              isActive: false,
            },
          }
        : {
            ...store!,
            status: "REJECTED",
            isActive: false,
            rejectionReason: reason,
            owner: {
              ...store!.owner,
              isActive: false,
            },
          };

      setStore(updatedStore);
      setBusy(false);
      setDialog(null);
      showFlash(t.admin.stores.didReject);
    },
    [storeId, store, showFlash],
  );

  const handleSuspendStore = useCallback(async () => {
    setBusy(true);
    setError("");

    const res = await suspendStore(storeId);
    if (!res.success) {
      setBusy(false);
      setDialog(null);
      const failure = classifyStatus(res);
      setError(
        failure.kind === "unauthorized"
          ? t.admin.common.sessionInvalid
          : failure.message,
      );
      return;
    }

    setStore((prev) => (prev ? { ...prev, isActive: false } : null));
    setBusy(false);
    setDialog(null);
    showFlash(t.admin.stores.didSuspend);
  }, [storeId, showFlash]);

  const handleActivateStore = useCallback(async () => {
    setBusy(true);
    setError("");

    const res = await activateStore(storeId);
    if (!res.success) {
      setBusy(false);
      setDialog(null);
      const failure = classifyStatus(res);
      setError(
        failure.kind === "unauthorized"
          ? t.admin.common.sessionInvalid
          : failure.message,
      );
      return;
    }

    setStore((prev) => (prev ? { ...prev, isActive: true } : null));
    setBusy(false);
    setDialog(null);
    showFlash(t.admin.stores.didActivate);
  }, [storeId, showFlash]);

  const handleFeatureStore = useCallback(async () => {
    setBusy(true);
    setError("");
    const res = await featureStore(storeId);
    if (!res.success) {
      setBusy(false);
      setDialog(null);
      const failure = classifyStatus(res);
      setError(failure.kind === "unauthorized" ? t.admin.common.sessionInvalid : failure.message);
      return;
    }
    setStore((prev) => (prev ? { ...prev, isFeatured: true } : null));
    setBusy(false);
    setDialog(null);
    showFlash(t.admin.stores.didFeature);
  }, [storeId, showFlash]);

  const handleUnfeatureStore = useCallback(async () => {
    setBusy(true);
    setError("");
    const res = await unfeatureStore(storeId);
    if (!res.success) {
      setBusy(false);
      setDialog(null);
      const failure = classifyStatus(res);
      setError(failure.kind === "unauthorized" ? t.admin.common.sessionInvalid : failure.message);
      return;
    }
    setStore((prev) => prev ? { ...prev, isFeatured: false, featuredOrder: null } : null);
    setBusy(false);
    setDialog(null);
    showFlash(t.admin.stores.didUnfeature);
  }, [storeId, showFlash]);

  const handleDeleteStore = useCallback(async () => {
    setBusy(true);
    setError("");

    const res = await deleteStore(storeId);
    if (!res.success) {
      setBusy(false);
      setDialog(null);
      if (res.ordersCount && res.ordersCount > 0) {
        setError(
          `لا يمكن حذف المتجر لوجود ${res.ordersCount} طلب/طلبات مسجلة عليه. يمكنك إيقافه أو حظره بدلاً من ذلك.`,
        );
        return;
      }
      const failure = classifyStatus(res);
      setError(
        failure.kind === "unauthorized"
          ? t.admin.common.sessionInvalid
          : (res.message || failure.message),
      );
      return;
    }

    setBusy(false);
    setDialog(null);
    showFlash("تم حذف المتجر وحساب التاجر نهائياً بنجاح 🗑️");
    router.push("/stores");
  }, [storeId, router, showFlash]);

  if (loading && validId) return <Spinner />;

  if (notFound || !validId) {
    return (
      <Card className="overflow-hidden border border-border shadow-xs">
        <CardBody className="p-8">
          <EmptyState
            icon={StoreIcon}
            title={t.admin.common.notFound}
            hint={t.admin.common.notFoundHint}
            action={
              <Button size="lg" onClick={() => router.push("/stores")}>
                {t.admin.common.backToList}
              </Button>
            }
          />
        </CardBody>
      </Card>
    );
  }

  if (!store) {
    return (
      <ErrorBanner
        message={error || t.admin.common.loadFailed}
        onRetry={() => {
          setLoading(true);
          setAttempt((a) => a + 1);
        }}
      />
    );
  }

  const broken =
    isBrokenText(store.name) ||
    isBrokenText(store.city) ||
    isBrokenText(store.owner?.name) ||
    isBrokenText(store.description) ||
    isBrokenText(store.address);

  const displayName = isBrokenText(store.name)
    ? `${t.admin.stores.brokenName}${store.id}`
    : store.name;

  return (
    <div className="flex flex-col gap-6">
      {/* Top Breadcrumb & Flash Notification */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-2 text-sm text-text-secondary">
          <button
            type="button"
            onClick={() => router.push("/stores")}
            className="font-bold transition hover:text-heading"
          >
            {t.admin.stores.title}
          </button>
          <span>/</span>
          <span className="font-bold text-heading">{displayName}</span>
        </div>

        <div className="flex items-center gap-3">
          {flash && (
            <span
              role="status"
              className="flex items-center gap-1.5 rounded-xl bg-success-soft px-3 py-1.5 text-xs font-bold text-success shadow-xs"
            >
              <Check className="size-4" aria-hidden="true" />
              {flash}
            </span>
          )}
          <Button
            variant="secondary"
            onClick={() => router.push("/stores")}
            icon={<ArrowLeft className="size-4 rtl:rotate-180" aria-hidden="true" />}
          >
            {t.admin.common.backToList}
          </Button>
        </div>
      </div>

      <ErrorBanner message={error} />

      {/* ⚠️ Broken Encoding Warning Banner */}
      {broken && (
        <Card className="border-warning/20 bg-warning-soft/40">
          <CardBody className="space-y-1">
            <p className="flex items-center gap-2 text-sm font-extrabold text-warning">
              <TriangleAlert className="size-4" aria-hidden="true" />
              {t.admin.stores.brokenTitle}
            </p>
            <p className="text-sm text-heading">{t.admin.stores.brokenBody}</p>
          </CardBody>
        </Card>
      )}

      {/* 🌟 Redesigned Store Hero Card */}
      <Card className="overflow-hidden border border-border shadow-xs">
        {/* Subtle cover gradient header */}
        <div className="h-28 w-full bg-linear-to-r from-primary/15 via-primary/5 to-field-bg" />

        <div className="relative px-6 pb-6 pt-0">
          <div className="flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between">
            {/* Logo + Identity Info */}
            <div className="flex flex-col gap-4 sm:flex-row sm:items-center">
              {/* Store Avatar Logo */}
              <div className="-mt-12 grid size-24 shrink-0 place-items-center overflow-hidden rounded-2xl border-4 border-surface bg-surface shadow-md">
                {store.logoUrl ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    src={store.logoUrl}
                    alt={store.name}
                    className="size-full object-cover"
                  />
                ) : (
                  <div className="grid size-full place-items-center bg-primary/10 text-primary">
                    <StoreIcon className="size-10" />
                  </div>
                )}
              </div>

              <div className="flex flex-col gap-1.5">
                <div className="flex flex-wrap items-center gap-2.5">
                  <h1 className="text-2xl font-black text-heading">
                    {displayName}
                  </h1>
                  <span className="ltr-nums rounded-lg bg-field-bg px-2.5 py-0.5 text-xs font-extrabold text-text-secondary">
                    #{store.id}
                  </span>
                </div>

                <div className="flex flex-wrap items-center gap-2 text-xs text-text-secondary">
                  {store.city && (
                    <span className="flex items-center gap-1 font-bold">
                      <MapPin className="size-3.5 text-primary" />
                      {store.city}
                    </span>
                  )}
                  {store.categories && store.categories.length > 0 && (
                    <span className="flex items-center gap-1">
                      <Tag className="size-3.5" />
                      {store.categories.map((c) => c.name).join("، ")}
                    </span>
                  )}
