            <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
              <div className="rounded-xl border border-border bg-field-bg p-3">
                <div className="flex items-center gap-1 text-[11px] font-semibold text-text-secondary">
                  <Package className="size-3.5 text-primary" />
                  <span>المنتجات المرتبطة</span>
                </div>
                <p className="mt-1 text-sm font-extrabold text-heading ltr-nums">
                  {formatNumber(occasion.productsCount)} منتج
                </p>
              </div>

              <div className="rounded-xl border border-border bg-field-bg p-3">
                <p className="text-[11px] font-semibold text-text-secondary">ترتيب العرض</p>
                <p className="mt-1 text-xs font-bold text-heading ltr-nums">
                  #{occasion.sortOrder}
                </p>
              </div>

              <div className="rounded-xl border border-border bg-field-bg p-3">
                <p className="text-[11px] font-semibold text-text-secondary">الظهور بالرئيسية</p>
                <p className="mt-1 text-xs font-bold text-heading">
                  {occasion.isFeaturedOnHome ? "مفعّل" : "غير مفعّل"}
                </p>
              </div>
            </div>

            {/* التصنيفات المشمولة */}
            {occasion.targetCategories && occasion.targetCategories.length > 0 && (
              <div className="rounded-xl border border-border bg-surface p-3.5">
                <p className="mb-2 text-[11px] font-semibold text-text-secondary">
                  التصنيفات المشمولة بهذا الفلتر:
                </p>
                <div className="flex flex-wrap gap-1.5">
                  {occasion.targetCategories.map((cat) => (
                    <span
                      key={cat}
                      className="rounded-lg bg-primary-soft/60 px-2.5 py-1 text-xs font-bold text-primary"
                    >
                      {cat}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* أزرار الإجراءات */}
          <div className="mt-6 flex flex-wrap items-center justify-between gap-2 border-t border-border pt-4">
            <div className="flex items-center gap-2">
              <Button
                variant="danger"
                size="sm"
                onClick={() => {
                  onClose();
                  onDelete(occasion);
                }}
                icon={<Trash2 className="size-3.5" />}
              >
                حذف الفلتر
              </Button>

              <Button
                variant="secondary"
                size="sm"
                onClick={() => {
                  onToggleActive(occasion);
                }}
                icon={occasion.isActive ? <EyeOff className="size-3.5" /> : <Eye className="size-3.5" />}
              >
                {occasion.isActive ? "تعطيل الفلتر" : "تفعيل الفلتر"}
              </Button>
            </div>

            <div className="flex items-center gap-2">
              <Button
                size="sm"
                onClick={() => {
                  onClose();
                  onEdit(occasion);
                }}
                icon={<Pencil className="size-3.5" />}
              >
                تعديل الفلتر
              </Button>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

"use client";

import {
  Activity,
  Briefcase,
  Coffee,
  Eye,
  EyeOff,
  Heart,
  Home,
  Moon,
  PartyPopper,
  Pencil,
  Plus,
  Sparkles,
  Sun,
  Tags,
  Trash2,
} from "lucide-react";
import Button from "@/components/ui/Button";
import Badge from "@/components/ui/Badge";
import { formatNumber } from "@/lib/format";
import type { OccasionFilter } from "@/lib/admin/types";

const ICON_MAP: Record<string, typeof Sparkles> = {
  sparkles: Sparkles,
  briefcase: Briefcase,
  coffee: Coffee,
  heart: Heart,
  "party-popper": PartyPopper,
  moon: Moon,
  activity: Activity,
  sun: Sun,
};

interface OccasionFilterListProps {
  occasions: OccasionFilter[];
  searchQuery: string;
  disabled: boolean;
  onSelectOccasion?: (item: OccasionFilter) => void;
  onAddNew: () => void;
  onEdit: (item: OccasionFilter) => void;
  onToggleActive: (item: OccasionFilter) => void;
  onToggleFeatured: (item: OccasionFilter) => void;
  onDelete: (item: OccasionFilter) => void;
}

export default function OccasionFilterList({
  occasions,
  searchQuery,
  disabled,
  onSelectOccasion,
  onAddNew,
  onEdit,
  onToggleActive,
  onToggleFeatured,
  onDelete,
}: OccasionFilterListProps) {
  const query = searchQuery.trim().toLowerCase();

  const filtered = occasions.filter((item) => {
    if (!query) return true;
    return (
      item.name.toLowerCase().includes(query) ||
      item.slug.toLowerCase().includes(query) ||
      item.description.toLowerCase().includes(query)
    );
  });

  if (filtered.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center rounded-2xl border border-dashed border-border bg-surface p-12 text-center">
        <div className="grid size-12 place-items-center rounded-2xl bg-primary-soft text-primary">
          <Tags className="size-6" />
        </div>
        <h3 className="mt-4 text-base font-bold text-heading">
          {searchQuery ? "لا توجد نتائج مطابقة للبحث" : "لا توجد وسوم وفلاتر مناسبات بعد"}
        </h3>
        <p className="mt-1 max-w-sm text-xs text-text-secondary">
          {searchQuery
            ? "جرّب البحث باسم آخر أو مسح حقل البحث."
            : "أضف فلاتر المناسبات (مثل: عمل، سهرة، أعياد) لتسهيل تصفية الملابس حسب المناسبة."}
        </p>
        {!searchQuery && (
          <Button
            className="mt-5"
            onClick={onAddNew}
            disabled={disabled}
            icon={<Plus className="size-4" aria-hidden="true" />}
          >
            إضافة فلتر مناسبة جديد
          </Button>
        )}
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
      {filtered.map((item) => {
        const IconComponent = ICON_MAP[item.icon] || Sparkles;

        return (
          <div
            key={item.id}
            className={`group relative flex flex-col justify-between rounded-2xl border bg-surface p-5 shadow-2xs transition-all hover:shadow-md ${
              item.isActive ? "border-border" : "border-border/60 opacity-75"
            }`}
          >
            <div
              onClick={() => onSelectOccasion?.(item)}
              className="cursor-pointer"
            >
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-3">
                  <div
                    className={`grid size-11 shrink-0 place-items-center rounded-xl transition-colors ${
                      item.isActive
                        ? "bg-primary-soft text-primary group-hover:bg-primary group-hover:text-white"
                        : "bg-field-bg text-text-secondary"
                    }`}
                  >
                    <IconComponent className="size-5" />
                  </div>
                  <div>
                    <h3 className="text-sm font-bold text-heading group-hover:text-primary transition">
                      {item.name}
                    </h3>
                    <p className="text-[11px] font-medium text-text-secondary dir-ltr text-right">
                      /{item.slug}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-1.5">
                  {item.isFeaturedOnHome && (
                    <Badge tone="primary">
                      <Home className="ml-1 size-3" />
                      الرئيسية
                    </Badge>
                  )}
                  <Badge tone={item.isActive ? "success" : "neutral"}>
                    {item.isActive ? "نشط" : "معطل"}
                  </Badge>
                </div>
              </div>

              {item.description && (
                <p className="mt-3 text-xs leading-relaxed text-text-secondary line-clamp-2">
                  {item.description}
                </p>
              )}

              {item.targetCategories && item.targetCategories.length > 0 && (
                <div className="mt-3 flex flex-wrap gap-1">
                  {item.targetCategories.map((cat) => (
                    <span
                      key={cat}
                      className="rounded-lg bg-field-bg px-2 py-0.5 text-[10px] font-semibold text-text-secondary"
                    >
                      {cat}
                    </span>
                  ))}
                </div>
              )}
            </div>

            <div className="mt-4 flex items-center justify-between border-t border-border/60 pt-3.5">
              <span className="text-xs font-semibold text-text-secondary">
                <span className="font-extrabold text-heading">
                  {formatNumber(item.productsCount)}
                </span>{" "}
                منتج مرتبط
              </span>

              <div className="flex items-center gap-1">
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => onToggleActive(item)}
                  disabled={disabled}
                  title={item.isActive ? "تعطيل الفلتر" : "تفعيل الفلتر"}
                  className="h-8 px-2 text-text-secondary hover:text-heading"
                >
                  {item.isActive ? (
                    <EyeOff className="size-4" />
                  ) : (
                    <Eye className="size-4" />
                  )}
                </Button>

                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => onEdit(item)}
                  disabled={disabled}
                  title="تعديل"
                  className="h-8 px-2 text-text-secondary hover:text-heading"
                >
                  <Pencil className="size-4" />
                </Button>

                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => onDelete(item)}
                  disabled={disabled}
                  title="حذف"
                  className="h-8 px-2 text-danger hover:bg-danger-soft"
                >
                  <Trash2 className="size-4" />
                </Button>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import {
  ArrowUpDown,
  Building2,
  Eye,
  Layers,
  MapPin,
  Package,
  Search,
  ShoppingBag,
  Store,
  User,
  XCircle,
} from "lucide-react";
import { Card } from "@/components/ui/Card";
import Badge from "@/components/ui/Badge";
import Button from "@/components/ui/Button";
import EmptyState from "@/components/ui/EmptyState";
import ErrorBanner from "@/components/ui/ErrorBanner";
import Pagination from "@/components/ui/Pagination";
import Spinner from "@/components/ui/Spinner";
import StatusBadge from "@/components/admin/StatusBadge";
import { TableShell, Td, Thead } from "@/components/ui/Table";
import { fetchStoreOrders, fetchAdminOrderDetail } from "@/lib/admin/api";
import { STORE_ORDER_STATUS } from "@/lib/admin/status";
import type {
  AdminOrderDetail,
  StoreOrder,
  StoreOrderStatus,
} from "@/lib/admin/types";
import { formatCurrency, formatDate } from "@/lib/format";
import { t } from "@/lib/strings";
import type { Pagination as PaginationType } from "@/lib/api";

const ORDER_COLUMNS = [
  t.admin.orders.colOrderNumber,
  t.admin.orders.colCustomer,
  t.admin.orders.colItems,
  t.admin.orders.colAddress,
  t.admin.orders.colDate,
  t.admin.orders.colTotal,
  t.admin.orders.colPayment,
  t.admin.orders.colStatus,
  t.admin.orders.colAction,
] as const;

interface TabConfig {
  key: string;
  label: string;
  status: StoreOrderStatus | "";
}

const TABS: TabConfig[] = [
  { key: "all", label: t.admin.orders.tabAll, status: "" },
  { key: "PENDING", label: "بانتظار الموافقة", status: "PENDING" },
  { key: "ACCEPTED", label: "قيد التجهيز", status: "ACCEPTED" },
  { key: "DELIVERED", label: "تم التوصيل", status: "DELIVERED" },
  { key: "CANCELLED", label: "ملغي", status: "CANCELLED" },
  { key: "REJECTED", label: "مرفوض", status: "REJECTED" },
];

export default function StoreOrdersSection({ storeId }: { storeId: number }) {
  const [orders, setOrders] = useState<StoreOrder[]>([]);
  const [counts, setCounts] = useState<Record<string, number>>({});
  const [pagination, setPagination] = useState<PaginationType | null>(null);
  const [activeTab, setActiveTab] = useState<string>("all");
  const [queryText, setQueryText] = useState("");
  const [sortOption, setSortOption] = useState<"newest" | "oldest" | "highest">("newest");
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedOrder, setSelectedOrder] = useState<StoreOrder | null>(null);
  const [orderDetail, setOrderDetail] = useState<AdminOrderDetail | null>(null);
  const [loadingDetail, setLoadingDetail] = useState(false);

  const handleOpenOrder = async (order: StoreOrder) => {
    setSelectedOrder(order);
    setLoadingDetail(true);
    setOrderDetail(null);
    try {
      const res = await fetchAdminOrderDetail(order.id);
      if (res.success && res.order) {
        setOrderDetail(res.order);
      }
    } catch {
      // fallback to selectedOrder
    } finally {
      setLoadingDetail(false);
    }
  };

  const loadOrders = useCallback(async () => {
    setLoading(true);
    setError("");

    const currentTabObj = TABS.find((tab) => tab.key === activeTab);
    const status = currentTabObj?.status || "";

    const res = await fetchStoreOrders(storeId, {
      page,
      limit: 10,
      q: queryText,
      status,
      sort: sortOption,
    });

    setLoading(false);

    if (res.success) {
      const rawList: any[] = Array.isArray(res.orders)
        ? res.orders
        : Array.isArray((res as any).data?.orders)
          ? (res as any).data.orders
          : Array.isArray((res as any).data)
            ? (res as any).data
            : [];

      const normalized: StoreOrder[] = rawList.map((o: any) => ({
        id: o.id ?? 0,
        orderNumber: o.orderNumber || o.code || (o.id ? `#${o.id}` : "—"),
        customerName: o.customerName || o.user?.name || o.customer?.name || "عميل فيورا",
        customerPhone: o.customerPhone || o.user?.phone || o.phone || null,
        customerEmail: o.customerEmail || o.user?.email || o.email || null,
        itemsCount: o.itemsCount ?? (Array.isArray(o.items) ? o.items.length : Array.isArray(o.orderItems) ? o.orderItems.length : 1),
        items: (o.items || o.orderItems || []).map((it: any) => ({
          id: it.id ?? 0,
          productName: it.productName || it.product?.name || "منتج",
          productImage: it.productImage || it.image || it.product?.imageUrl || it.product?.image || null,
          colorName: it.colorName || it.color || null,
          sizeName: it.sizeName || it.size || null,
          variant: it.variant || it.color || null,
          size: it.size || null,
          quantity: it.quantity ?? 1,
          unitPrice: String(it.unitPrice ?? it.price ?? 0),
          lineTotal: String(it.lineTotal ?? (Number(it.unitPrice ?? it.price ?? 0) * Number(it.quantity ?? 1))),
          price: String(it.unitPrice ?? it.price ?? 0),
        })),
        city: o.city || o.address?.city || "—",
        address: o.address?.street || (typeof o.address === "string" ? o.address : o.city || "—"),
        createdAt: o.createdAt || new Date().toISOString(),
        total: String(o.total ?? o.totalPrice ?? o.amount ?? 0),
        shippingFee: o.shippingFee ? String(o.shippingFee) : undefined,
        paymentMethod: o.paymentMethod || (o.paymentType === "COD" ? "CASH_ON_DELIVERY" : "ONLINE"),
        status: o.status || "NEW",
      }));

      setOrders(normalized);

      const rawCounts =
        (res as any).statusCounts ||
        res.counts ||
        (res as any).data?.statusCounts ||
        (res as any).data?.counts;

      if (rawCounts) {
        const total =
          res.pagination?.total ??
          (res as any).data?.pagination?.total ??
          Object.values(rawCounts).reduce(
            (acc: number, val: any) => acc + (Number(val) || 0),
            0,
          );
        setCounts({ ...rawCounts, all: total });
      } else {
        const computed: Record<string, number> = { all: normalized.length };
        normalized.forEach((ord) => {
          computed[ord.status] = (computed[ord.status] || 0) + 1;
        });
        setCounts(computed);
      }

      const rawPagination = res.pagination || (res as any).data?.pagination;
      if (rawPagination) setPagination(rawPagination);
    } else {
      setError(res.message || t.admin.common.loadFailed);
    }
  }, [storeId, activeTab, queryText, sortOption, page]);

  useEffect(() => {
    loadOrders();
  }, [loadOrders]);

  return (
    <div className="flex flex-col gap-6">
      {/* Header & Subtitle */}
      <div className="flex flex-col gap-1">
        <h2 className="text-xl font-extrabold text-heading">
          {t.admin.orders.title}
        </h2>
        <p className="text-sm text-text-secondary">
          {t.admin.orders.subtitle}
        </p>
      </div>

      <ErrorBanner message={error} onRetry={loadOrders} />

      {/* Tabs with Count Pills */}
      <div className="flex flex-wrap items-center gap-2 overflow-x-auto pb-1">
        {TABS.map((tab) => {
          const isActive = activeTab === tab.key;
          const count = counts[tab.key] ?? (tab.key === "all" ? counts.all : 0);

          return (
            <button
              key={tab.key}
              type="button"
              onClick={() => {
                setActiveTab(tab.key);
                setPage(1);
              }}
              className={`flex items-center gap-2 rounded-xl px-4 py-2 text-xs font-extrabold transition ${
                isActive
                  ? "bg-primary text-white shadow-xs"
                  : "border border-border/80 bg-surface text-text-secondary hover:border-primary/40 hover:text-heading"
              }`}
            >
              <span>{tab.label}</span>
              {typeof count === "number" && (
                <span
                  className={`rounded-full px-2 py-0.5 text-[11px] font-bold ${
                    isActive
                      ? "bg-white/20 text-white"
                      : "bg-field-bg text-text-secondary"
                  }`}
                >
                  {count}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {/* Search & Sort Toolbar */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative flex-1">
          <Search className="absolute right-3.5 top-1/2 size-4 -translate-y-1/2 text-text-secondary" />
          <input
            type="search"
            value={queryText}
            onChange={(e) => {
              setQueryText(e.target.value);
              setPage(1);
            }}
            placeholder={t.admin.orders.searchPlaceholder}
            className="h-10.5 w-full rounded-xl border border-border bg-surface pl-4 pr-10 text-sm text-heading placeholder:text-text-secondary/70 focus:border-primary focus:outline-hidden focus:ring-2 focus:ring-primary/20"
          />
        </div>

        <div className="flex items-center gap-2">
          <div className="relative">
            <select
              value={sortOption}
              onChange={(e) => {
                setSortOption(e.target.value as "newest" | "oldest" | "highest");
                setPage(1);
              }}
              className="h-10.5 appearance-none rounded-xl border border-border bg-surface pl-8 pr-4 text-xs font-bold text-heading hover:border-primary/40 focus:border-primary focus:outline-hidden"
            >
              <option value="newest">{t.admin.orders.sortNewest}</option>
              <option value="oldest">{t.admin.orders.sortOldest}</option>
              <option value="highest">{t.admin.orders.sortHighest}</option>
            </select>
            <ArrowUpDown className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-text-secondary" />
          </div>
        </div>
      </div>

      {/* Orders Table or Empty State */}
      {loading ? (
        <Card className="p-12">
          <Spinner />
        </Card>
      ) : orders.length === 0 ? (
        <Card className="border border-border p-8">
          <EmptyState
            icon={ShoppingBag}
            title={queryText || activeTab !== "all" ? t.admin.orders.noResults : t.admin.orders.empty}
            hint={t.admin.orders.emptyHint}
            action={
              queryText || activeTab !== "all" ? (
                <Button
                  variant="secondary"
                  size="sm"
                  onClick={() => {
                    setQueryText("");
                    setActiveTab("all");
                    setPage(1);
                  }}
                >
                  {t.admin.common.clearSearch}
                </Button>
              ) : undefined
            }
          />
        </Card>
      ) : (
        <div className="flex flex-col gap-4">
          <Card className="overflow-hidden border border-border shadow-xs">
            <TableShell minWidth="min-w-[950px]">
              <Thead columns={ORDER_COLUMNS} />
              <tbody className="divide-y divide-border/60">
                {orders.map((order) => (
                  <tr
                    key={order.id}
                    className="transition hover:bg-primary-soft/30"
                  >
                    <Td>
                      <span className="font-extrabold text-heading">
                        {order.orderNumber}
                      </span>
                    </Td>
                    <Td>
                      <div className="flex flex-col">
                        <span className="font-bold text-heading">
                          {order.customerName}
                        </span>
                        {order.customerPhone && (
                          <span className="ltr-nums text-xs text-text-secondary">
                            {order.customerPhone}
                          </span>
                        )}
                      </div>
                    </Td>
                    <Td className="ltr-nums font-medium text-text-secondary">
                      {order.itemsCount}
                    </Td>
                    <Td className="max-w-[200px] truncate text-text-secondary">
                      {order.address || order.city}
                    </Td>
                    <Td className="ltr-nums whitespace-nowrap text-text-secondary">
                      {formatDate(order.createdAt)}
                    </Td>
                    <Td>
                      <span className="ltr-nums font-bold text-heading">
                        {formatCurrency(Number(order.total))}
                      </span>
                    </Td>
                    <Td>
                      <Badge tone={order.paymentMethod === "ONLINE" ? "info" : "neutral"}>
                        {order.paymentMethod === "ONLINE"
                          ? t.admin.orders.paymentOnline
                          : t.admin.orders.paymentCOD}
                      </Badge>
                    </Td>
                    <Td>
                      <StatusBadge meta={STORE_ORDER_STATUS[order.status]} />
                    </Td>
                    <Td>
                      <Button
                        size="sm"
                        variant="secondary"
                        onClick={() => handleOpenOrder(order)}
                        icon={<Eye className="size-3.5" />}
                      >
                        {t.admin.orders.reviewOrder}
                      </Button>
                    </Td>
                  </tr>
                ))}
              </tbody>
            </TableShell>
          </Card>

          {pagination && pagination.totalPages > 1 && (
            <Pagination
              pagination={pagination}
              onChange={(newPage) => setPage(newPage)}
            />
          )}
        </div>
      )}

      {/* Order Detail Modal Dialog */}
      {selectedOrder && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div
            className="fixed inset-0 bg-black/40 backdrop-blur-xs transition-opacity"
            onClick={() => {
              setSelectedOrder(null);
              setOrderDetail(null);
            }}
          />

          <div className="relative z-10 max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-3xl border border-border bg-app-bg shadow-2xl">
            <div className="sticky top-0 z-10 flex items-start justify-between border-b border-border bg-surface px-6 py-5 sm:px-8">
              <div className="flex flex-col gap-1">
                <div className="flex items-center gap-2">
                  <h3 className="text-lg font-extrabold text-heading">
                    {t.admin.orders.detailsTitle}
                  </h3>
                </div>
                <p className="text-xs text-text-secondary">
                  {orderDetail?.orderNumber || selectedOrder.orderNumber} · {formatDate(orderDetail?.createdAt || selectedOrder.createdAt)}
                </p>
              </div>
              <button
                type="button"
                onClick={() => {
                  setSelectedOrder(null);
                  setOrderDetail(null);
                }}
                className="grid size-9 place-items-center rounded-xl text-text-secondary hover:bg-field-bg hover:text-heading cursor-pointer"
              >
                <XCircle className="size-5" />
              </button>
