const LATENCY_MS = 320;

/**
 * محاكاة الأعطال لاختبار حالات الخطأ والفراغ.
 * `network` = فشل شبكة (status 0) · `server` = 500 · `empty` = قوائم فاضية.
 */
const FAIL_MODE = process.env.NEXT_PUBLIC_ADMIN_MOCK_FAIL ?? "";

